import{_ as n}from"./peer-result-loop-a6370db4.js";import{_ as a}from"./plugin-vue_export-helper-c27b6911.js";import{r as o,o as i,c as r,d as t,e,b as d,w as l,a as c,f as h}from"./app-79a937d1.js";const u={},p=t("strong",null,"how does the result get back to whoever sent the message?",-1),m=t("p",null,"This post records the final design — asynchronous result routing — and the bugs found along the way. None of them are exotic, but each one made the whole link look completely dead.",-1),b=h('<h2 id="_1-final-shape" tabindex="-1"><a class="header-anchor" href="#_1-final-shape" aria-hidden="true">#</a> 1. Final shape</h2><figure><img src="'+n+`" alt="Asynchronous result routing" tabindex="0" loading="lazy"><figcaption>Asynchronous result routing</figcaption></figure><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>macmini: peer_send / peer_reply (optional targetSessionId)
  → send, then end the turn (system prompt: do not poll)
hub: deliver to a hub-owned session (Peer Inbox)
  → run one turn
  → at turn/end, take the final assistant text
  → query session/state
  → steer when running, prompt when idle
  → push \`[hub] &lt;text&gt;\` back to the initiating macmini session
macmini: receive [hub] ... → continue with the next round
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>No blocking, no polling, and no dependency on the hub agent remembering to reply.</p><h2 id="_2-ownership-the-hub-cannot-write-into-gui-sessions" tabindex="-1"><a class="header-anchor" href="#_2-ownership-the-hub-cannot-write-into-gui-sessions" aria-hidden="true">#</a> 2. Ownership: the hub cannot write into GUI sessions</h2><p>The least intuitive constraint. In DSH every agent has an owner:</p><ul><li>a GUI session&#39;s agent is created and held by the GUI session controller</li><li>the peer plugin&#39;s <code>agents.get(id)</code> returns nothing, and <code>resume</code> fails too</li></ul><p>So &quot;deliver into the session the user is watching&quot; is not possible from a plugin. The solution is a session the hub creates itself:</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>session id: peer-inbox (or peer-inbox-xxxx)
owner:      the hub plugin
visible:    attached to a workspace, so it appears in the GUI
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Peer messages default there, its agent runs a turn, and the result is pushed back to macmini. A dedicated mailroom for peer traffic.</p><h2 id="_3-steer-or-prompt" tabindex="-1"><a class="header-anchor" href="#_3-steer-or-prompt" aria-hidden="true">#</a> 3. steer or prompt</h2><p>The remote side may be running or idle when the result arrives:</p><table><thead><tr><th>Remote state</th><th>Mechanism</th><th>Effect</th></tr></thead><tbody><tr><td>running</td><td><code>session/steer</code></td><td>injected at the next step; polling stops</td></tr><tr><td>idle</td><td><code>session/prompt</code></td><td>starts a turn with <code>[hub]</code> as input</td></tr></tbody></table><p>Cached status is not trustworthy (<code>session.status</code> notifications never arrived), so query the link:</p><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">const</span> state <span class="token operator">=</span> <span class="token keyword">await</span> link<span class="token punctuation">.</span>conn<span class="token punctuation">.</span><span class="token function">request</span><span class="token punctuation">(</span><span class="token string">&#39;session/state&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> sessionId <span class="token punctuation">}</span><span class="token punctuation">)</span>
<span class="token keyword">const</span> running <span class="token operator">=</span> state<span class="token operator">?.</span>status <span class="token operator">!==</span> <span class="token string">&#39;idle&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_4-the-real-bugs" tabindex="-1"><a class="header-anchor" href="#_4-the-real-bugs" aria-hidden="true">#</a> 4. The real bugs</h2><table><thead><tr><th>Symptom</th><th>Root cause</th><th>Fix</th></tr></thead><tbody><tr><td>macmini never receives results</td><td><code>const sessionId = agent.session.id</code> inside <code>#deliverToAgent</code> <strong>shadowed the parameter</strong>, so <code>remoteSessionId</code> became the local id</td><td>local id only as the map key; keep the remote id</td></tr><tr><td>new session throws <code>unknown peer session</code></td><td><code>working-directory/set</code> called before the session exists</td><td>ignore the error; the new session takes its cwd from <code>peer/prepare-session</code></td></tr><tr><td>hub finds no agent, messages land in pending</td><td>ownership isolation: GUI sessions are not writable</td><td>deliver to a hub-owned Peer Inbox</td></tr><tr><td>results always take the prompt path and queue</td><td>cached <code>session.status</code> stays idle forever</td><td>query <code>session/state</code> before pushing</td></tr><tr><td>busy sessions wait for the whole turn</td><td><code>followup</code> only queues</td><td>steer when running</td></tr></tbody></table><p>The first bug is the archetype: it throws nothing, delivery works, but the push targets a session that does not exist. From the outside the link simply &quot;does not answer&quot;.</p><h2 id="_5-how-to-verify" tabindex="-1"><a class="header-anchor" href="#_5-how-to-verify" aria-hidden="true">#</a> 5. How to verify</h2><p>Do not trust &quot;it should work now&quot;. Leave evidence:</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>~/.dsh/peer-push.log
2026-11-07T16:16:42.002Z pushed prompt peer-macmini-fix1 bytes=46
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>And what macmini actually received:</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>[hub] 收到，已忽略。

（hub 已完成这一轮，直接继续即可，不需要轮询。）
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Push log on one side, received text on the other — that is a closed loop.</p><h2 id="_6-the-cost-of-initiator-side-choice" tabindex="-1"><a class="header-anchor" href="#_6-the-cost-of-initiator-side-choice" aria-hidden="true">#</a> 6. The cost of initiator-side choice</h2><p>&quot;Whoever initiates chooses the target&quot; was the agreed direction:</p><ul><li>the link asks its local user which hub session to use</li><li>without <code>targetSessionId</code> a card appears; if nobody answers, the send is cancelled</li></ul><p>That is correct for interactive use but blocking for unattended work. Mitigations: remember the last choice, or default to a well-known target such as <code>peer-inbox</code>.</p><h2 id="_7-what-was-removed" tabindex="-1"><a class="header-anchor" href="#_7-what-was-removed" aria-hidden="true">#</a> 7. What was removed</h2><p>An intermediate <code>peer_ask_hub</code> tool sent a message and waited synchronously for the hub turn&#39;s text. It duplicated the async push and:</p><ul><li>blocked the caller</li><li>waited forever when the hub session was busy</li><li>could deadlock if the hub called back synchronously</li></ul><p>It was removed. <strong>Prefer async unless you truly need a reply in the same call.</strong></p><h2 id="_8-lessons" tabindex="-1"><a class="header-anchor" href="#_8-lessons" aria-hidden="true">#</a> 8. Lessons</h2><ul><li><strong>Understand ownership first</strong>: a plugin can only write to sessions it owns</li><li><strong>The push id must be the remote id</strong>: a same-named local variable is a disaster</li><li><strong>Do not trust cached status</strong>: one <code>session/state</code> call beats notification bookkeeping</li><li><strong>Confirm the process really restarted</strong>: a scheduled restart silently did not run, and an old process wasted a long test</li><li><strong>Add the log first</strong>: <code>peer-push.log</code> turned a mystery into one line of failure</li></ul>`,34);function g(v,w){const s=o("RouterLink");return i(),r("div",null,[t("p",null,[e("The "),d(s,{to:"/en/architecture/dsh-peer-selection.html"},{default:l(()=>[e("previous post")]),_:1}),e(" covered choosing a session. The real problem appeared afterwards: "),p]),m,c(" more "),b])}const x=a(u,[["render",g],["__file","dsh-peer-result-push.html.vue"]]);export{x as default};
